.", "params": ["p.immediate_hazard_gap"], "narrowings": [{"span": "s1", "why": "Control of traffic is read as control of x's own approach or intersection; officer and signal presence are read as their status.", "kind": "observable_reading", "category": "status"}, {"span": "s2", "why": "'proper signs' are read through the presence of a stop or yield sign.", "kind": "observable_reading", "category": "status"}, {"span": "s3", "why": "'the driver' is read through the vehicle's controlled motion.", "kind": "observable_reading", "category": "agency"}, {"span": "s10", "why": "The yield is judged at x's entry into the intersection.", "kind": "reading"}, {"span": "s12", "why": "'during the time such driver is moving across or within the intersection' is read through the critical gap, not through a prediction of x's own crossing time; 'such through highway' is a highway the intersection lies on and x's signed approach does not.", "kind": "reading"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "dev.stop_sign governs c; x halts at the stop line marking c, then enters i while vehicle y on approach carrier c2 of the crossing highway h2 is 25 m from i at 15 m/s."}, {"name": "permit", "expected": "compliant", "narrative": "As forbid, but x enters i as the only road user in the scene."}, {"name": "idle", "expected": "not_applicable", "narrative": "No sign governs c or i; x enters i."}, {"name": "blind", "expected": "unknown", "narrative": "As forbid, but kin.speed is not observed.", "masked": ["kin.speed"]}, {"name": "branch_1", "expected": "violated", "narrative": "x halts at its stop line and enters i while vehicle y, which entered i through c2 on h2, occupies i."}, {"name": "branch_2", "expected": "not_applicable", "narrative": "As forbid, but x never halted or slowed on the approach (NRS_484B_257_1_o1 not complied with): this duty does not arise."}], "literals": [], "param_proposals": [{"name": "p.immediate_hazard_gap", "unit": "s", "value": 4.1, "conv