{"node_id": "NRS_484B_297_6_o1", "law_refs": ["NRS-484B-297-6"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-165::pedestrian"]}, "segmentation": [{"id": "s1", "text": "A pedestrian", "role": "subject"}, {"id": "s2", "text": "walking or otherwise traveling on a sidewalk", "role": "condition"}, {"id": "s3", "text": "who encounters an obstruction to his or her mobility on the sidewalk,", "role": "condition"}, {"id": "s4", "text": "including, without limitation, a short section of the sidewalk that is missing or impassable,", "role": "condition"}, {"id": "s5", "text": "may proceed", "role": "obligation"}, {"id": "s6", "text": "with due care", "role": "standard"}, {"id": "s7", "text": "on the immediately adjacent highway to move around such an obstruction.", "role": "condition"}, {"id": "s8", "text": "Such a pedestrian:", "role": "subject"}, {"id": "s9", "text": "(a) Must walk or otherwise travel as far to the side of the highway near the sidewalk", "role": "sibling"}, {"id": "s10", "text": "as possible;", "role": "sibling"}, {"id": "s11", "text": "(b) May walk or otherwise travel on the highway in the direction he or she was walking or traveling on the sidewalk, regardless of the direction of traffic;", "role": "condition"}, {"id": "s12", "text": "(c) May walk or otherwise travel in a lane provided for bicycles, electric bicycles or electric scooters", "role": "sibling"}, {"id": "s13", "text": "if the area between the lane and the sidewalk is impassable;", "role": "sibling"}, {"id": "s14", "text": "and", "role": "boilerplate"}, {"id": "s15", "text": "(d) Must return to the sidewalk", "role": "sibling"}, {"id": "s16", "text": "as soon as practicable.", "role": "sibling"}], "elements": [{"span": "s1", "atoms": ["ru.aggregate=DEF-NRS-484A-165::pedestrian"], "derived": [], "justification": "'pedestrian' is the admitted aggregate DEF-NRS-484A-165::pedestrian ('a person afoot, a person in a manual or motorized wheelchair, or a person on an electri