ntry.", "masked": ["rel.occupies"]}, {"name": "branch_1", "expected": "violated", "narrative": "A dev.traffic_signal governing i is dev.inoperative (NRS_484B_250_4_o1 applies); y entered i from a different highway; x enters i while y occupies it."}, {"name": "branch_2", "expected": "compliant", "narrative": "At a skewed junction, y entered i through c2 on another highway whose designated direction is opposed to c's, and int.left_turn y i is declared; x enters while y is in i: the pair is excepted."}], "literals": [], "param_proposals": [{"name": "p.opposed_carriers_cosine", "unit": "ratio", "value": 0.7, "convention": "Direction tolerance: minus the cosine of the narrowest angle between two carriers' designated directions that counts as opposite directions; carriers within about 45 degrees of exactly opposed count.", "source": "Junction geometry: approaches meeting at an intersection skewed by up to 45 degrees (AASHTO Green Book ch. 9)"}, {"name": "p.turn_recognition_angle", "unit": "deg", "value": 45, "convention": "Turn recognition: the heading change through an intersection beyond which a passage counts as a turn rather than a straight crossing; half the right angle of a turn at a right-angled junction, leaving room for skewed junctions and lane offsets.", "source": "Geometry of a right-angled junction (AASHTO Green Book ch. 9 intersection angles)"}], "gaps": []}
