s": [{"span": "s1", "why": "'the driver' is read through the vehicle's controlled motion.", "kind": "observable_reading", "category": "agency"}, {"span": "s2", "why": "'about to enter or exit' is read by the entry into or exit from the controlled-access region.", "kind": "observable_reading", "category": "intention"}, {"span": "s6", "why": "Continuing to yield until the driver may proceed is read at the entry or exit observation: the manoeuvre is made only when the safety margin holds.", "kind": "reading"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "x enters controlled-access region a at 15 m/s while vehicle y in a, moving at 30 m/s and approaching x, is at rel.surface_gap 20 m."}, {"name": "permit", "expected": "compliant", "narrative": "x enters a as the only road user in the scene."}, {"name": "idle", "expected": "not_applicable", "narrative": "x drives on an arterial; no st.controlled_access region is entered or left."}, {"name": "blind", "expected": "unknown", "narrative": "As forbid, but rel.surface_gap is not observed.", "masked": ["rel.surface_gap"]}, {"name": "branch_1", "expected": "compliant", "narrative": "x enters a while y, approaching at 30 m/s, is at rel.surface_gap 90 m."}], "literals": [], "param_proposals": [{"name": "p.speed_resolution", "unit": "m/s", "value": 0.2, "convention": "Sensor resolution: the smallest speed the acquisition standard separates from standstill; a speed at or below it counts as no motion.", "source": "carla_scene_graph acquisition standard: speed resolution of the recorded kinematics"}, {"name": "p.immediate_hazard_gap", "unit": "s", "value": 4.1, "convention": "Critical gap: the time within which another road user's arrival at the conflict area, or its predicted closest approach, counts as an immediate hazard to a road user about to cross or join its path.", "source": "HCM 7th ed. Exhibit 20-11 base critical headway (major-street left turn)"}, {"name": "p.merge_time_headway", "unit": "s", "value": 2.0, "convention": "Safe merge headway: the time an approaching vehicle on the highway would take, at its own speed, to close the gap to a vehicle entering or leaving the highway; a smaller gap is not reasonable safety.", "source": "Two-second following rule; HCM freeway merge gap acceptance"}], "gaps": []}
{"node_id": "NRS_484B_297_6_o1", "law_refs": ["NRS-484B-297-6"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-165::pedestrian"]}, "segmentation": [{"id": "s1", "text": "A pedestrian", "role": "subject"}, {"id": "s2", "text": "walking or otherwise traveling on a sidewalk", "role": "condition"}, {"id": "s3", "text": "who encounters an obstruction to his or her mobility on the sidewalk,", "role": "condition"}, {"id": "s4", "text": "including, without limitation, a short section of the sidewalk that is missing or impassable,", "role": "condition"}, {"id": "s5", "text": "may proceed", "role": "obligation"}, {"id": "s6", "text": "with due care", "role": "standard"}, {"id": "s7", "text": "on the immediately adjacent highway to move around such an obstruction.", "role": "condition"}, {"id": "s8", "text": "Such a pedestrian:", "role": "subject"}, {"id": "s9", "text": "(a) Must walk or otherwise travel as far to the side of the highway near the sidewalk", "role": "sibling"}, {"id": "s10", "text": "as possible;", "role": "sibling"}, {"id": "s11", "text": "(b) May walk or otherwise travel on the highway in the direction he or she was walking or traveling on the sidewalk, regardless of the direction of traffic;", "role": "condition"}, {"id": "s12", "text": "(c) May walk or otherwise travel in a lane provided for bicycles, electric bicycles or electric scooters", "role": "sibling"}, {"id": "s13", "text": "if the area between the lane and the sidewalk is impassable;", "role": "sibling"}, {"id": "s14", "text": "and", "role": "boilerplate"}, {"id": "s15", "text": "(d) Must return to the sidewalk", "role": "sibling"}, {"id": "s16", "text": "as soon as practicable.", "role": "sibling"}], "elements": [{"span": "s1", "atoms": ["ru.aggregate=DEF-NRS-484A-165::pedestrian"], "derived": [], "justification": "'pedestrian' is the admitted aggregate DEF-NRS-484A-165::pedestrian ('a person afoot, a person in a manual or motorized wheelchair, or a person on an electri