{"node_id": "NRS_484B_253_o2", "law_refs": ["NRS-484B-253"], "subject": {"binder": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "s1", "text": "The driver of a vehicle", "role": "condition"}, {"id": "s2", "text": "within an intersection", "role": "condition"}, {"id": "s3", "text": "intending to turn to the left", "role": "condition"}, {"id": "s4", "text": "shall yield the right-of-way", "role": "sibling"}, {"id": "s5", "text": "to any vehicle approaching from the opposite direction", "role": "sibling"}, {"id": "s6", "text": "which is within the intersection", "role": "sibling"}, {"id": "s7", "text": "or so close thereto as to constitute an immediate hazard,", "role": "sibling"}, {"id": "s8", "text": "but such driver, having so yielded", "role": "condition"}, {"id": "s9", "text": "and having given a signal", "role": "condition"}, {"id": "s10", "text": "when and as required,", "role": "reference"}, {"id": "s11", "text": "may make such left turn", "role": "condition"}, {"id": "s12", "text": "and the drivers of all other vehicles", "role": "subject"}, {"id": "s13", "text": "approaching the intersection from the opposite direction", "role": "trigger"}, {"id": "s14", "text": "shall yield the right-of-way", "role": "obligation"}, {"id": "s15", "text": "to the vehicle making the left turn.", "role": "condition"}], "elements": [{"span": "s1", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "The turning vehicle y is of the admitted aggregate DEF-NRS-484A-320::vehicle; 'the driver' is read through its controlled motion."}, {"span": "s2", "atoms": ["rel.occupies", "st.intersection"], "derived": [], "justification": "'within an intersection': rel.occupies 'a road user's footprint overlaps a lane / region' of y and the st.intersection x approaches."}, {"span": "s9", "atoms": ["sig.turn_indicator", "sig.hand_signal", "rel.occupies", "st.travel_region", "st.intersection"], "derived": ["drv.position.e